import com.lightning.northstar.content.NorthstarBlocks;
import com.simibubi.create.AllBlocks;
import com.simibubi.create.foundation.ponder.CreateSceneBuilder;
import net.createmod.ponder.api.scene.SceneBuilder;
import net.createmod.ponder.api.scene.SceneBuildingUtil;
import net.createmod.ponder.api.scene.SelectionUtil;
import net.minecraft.core.Direction;
import net.minecraft.world.level.block.PipeBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.Property;

public class CombustionEnginePonder {
    public static void program(SceneBuilder sceneBuilder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(sceneBuilder);
        SelectionUtil select = util.select();
        CreateSceneBuilder.WorldInstructions world = scene.world();
        scene.title("combustion_engine", "Generating Rotational Force using Combustion Engines");
        scene.setSceneOffsetY(-2.0f);
        scene.configureBasePlate(1, 1, 5);
        scene.removeShadow();
        scene.addKeyframe();
        world.showSection(select.layer(0), Direction.UP);
        world.showSection(select.fromTo(1, 1, 1, 5, 1, 5), Direction.UP);
        scene.idle(5);
        world.showSection(select.position(4, 2, 3), Direction.DOWN);
        world.showSection(select.position(2, 2, 3), Direction.DOWN);
        scene.idle(5);
        world.showSection(select.position(4, 3, 3), Direction.DOWN);
        scene.idle(5);
        world.showSection(select.position(3, 3, 3), Direction.DOWN);
        scene.idle(5);
        world.showSection(select.position(2, 3, 3), Direction.DOWN);
        scene.overlay().showOutlineWithText(select.position(4, 3, 3), 80).text("Combustion Engines burn fuel to produce kinetic force");
        scene.idle(90);
        scene.addKeyframe();
        world.showSection(select.fromTo(6, 1, 1, 6, 4, 6), Direction.WEST);
        world.showSection(select.position(5, 3, 3), Direction.WEST);
        world.setKineticSpeed(select.position(6, 1, 2), 32.0f);
        world.setKineticSpeed(select.position(6, 2, 2), 32.0f);
        world.setKineticSpeed(select.position(6, 2, 3), -32.0f);
        world.propagatePipeChange(util.grid().at(6, 2, 3));
        scene.idle(10);
        scene.overlay().showOutlineWithText(select.position(5, 3, 3), 80).text("Fuel must be inserted on the side opposite of the shaft");
        scene.idle(40);
        world.setKineticSpeed(select.fromTo(2, 3, 3, 4, 3, 3), 32.0f);
        scene.idle(50);
        scene.overlay().showOutlineWithText(select.position(2, 3, 3), 80).text("And the engine will start automatically");
        scene.idle(90);

